// Transforma o evento do WhatsApp em um formato simples para o agente.
// Só mensagens de clientes chegam aqui: status de entrega são filtrados no gatilho.
const saida = [];

for (const item of $input.all()) {
  const v = item.json;
  const msg = (v.messages || [])[0];
  if (!msg) continue;

  const contato = (v.contacts || [])[0] || {};
  let texto = '';

  switch (msg.type) {
    case 'text':
      texto = msg.text?.body || '';
      break;
    case 'button':
      texto = msg.button?.text || '';
      break;
    case 'interactive':
      texto = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
      break;
    case 'audio':
      texto = '[O cliente enviou um áudio. Você não consegue ouvir áudios: peça com gentileza para escrever a dúvida em texto.]';
      break;
    case 'image':
    case 'video':
    case 'document':
    case 'sticker': {
      const legenda = msg[msg.type]?.caption;
      texto = `[O cliente enviou um arquivo do tipo ${msg.type}${legenda ? ' com a legenda: ' + legenda : ''}. ` +
        'Você não vê arquivos: responda com base na legenda, se houver, e explique que fotos são avaliadas pela Dra. na consulta.]';
      break;
    }
    default:
      texto = `[O cliente enviou uma mensagem do tipo ${msg.type}.]`;
  }

  saida.push({
    json: {
      canal: 'whatsapp',
      sessionId: 'wa-' + msg.from,
      telefone: msg.from,
      nome: contato.profile?.name || '',
      texto: texto.slice(0, 1500),
      phoneNumberId: v.metadata?.phone_number_id || '',
      messageId: msg.id
    }
  });
}

return saida;

// Mensagem vinda do chat do site (assets/js/chat.js).
const saida = [];

for (const item of $input.all()) {
  const body = item.json.body || {};
  const texto = String(body.message || '').trim().slice(0, 500);
  const id = String(body.sessionId || '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 64) || ('anon-' + Date.now());

  saida.push({
    json: {
      canal: 'site',
      sessionId: 'site-' + id.replace(/^site-/, ''),
      telefone: '',
      nome: '',
      texto: texto || 'Olá',
      phoneNumberId: ''
    }
  });
}

return saida;

// ===== CONFIGURAÇÃO (edite aqui) =====
const NUMERO_ERICA = '5543996602325';   // WhatsApp da Érica (app WhatsApp Business), só dígitos
const LINK_CATALOGO = '';               // link copiado no app; vazio = https://wa.me/c/<NUMERO_ERICA>
// =====================================

function linkWhats(texto) {
  return `https://wa.me/${NUMERO_ERICA}?text=${encodeURIComponent(texto)}`;
}

function dadosDe(nomeDoNo) {
  try {
    const no = $(nomeDoNo);
    if (no.isExecuted === false) return null;
    const primeiro = no.first();
    return primeiro ? primeiro.json : null;
  } catch (erro) {
    return null;
  }
}

const origem = dadosDe('Normalizar WhatsApp') || dadosDe('Normalizar site') || {};
const canal = origem.canal || 'site';
const saida = [];

for (const item of $input.all()) {
  let texto = String(item.json.output ?? '').trim();

  if (!texto) {
    texto = 'Desculpe, tive uma instabilidade agora. Para não te deixar esperando, fale direto com a equipe:\n[[HUMANO]]';
  }

  texto = texto.replace(/\[\[AGENDAR\|([^|\]]*)\|([^|\]]*)\|([^\]]*)\]\]/g, (m, nome, interesse, periodo) =>
    linkWhats(
      'Olá! Vim pelo assistente da Clínica Antolli e quero agendar.\n' +
      `Nome: ${nome.trim()}\nInteresse: ${interesse.trim()}\nMelhor período: ${periodo.trim()}`
    )
  );
  texto = texto.replace(/\[\[URGENTE\]\]/g,
    linkWhats('URGENTE: fiz um procedimento na Clínica Antolli e estou com uma intercorrência. Preciso falar com a Dra. Érica.'));
  texto = texto.replace(/\[\[HUMANO\]\]/g,
    linkWhats('Olá! Vim pelo assistente da Clínica Antolli e quero falar com a equipe.'));
  texto = texto.replace(/\[\[CATALOGO\]\]/g, LINK_CATALOGO || `https://wa.me/c/${NUMERO_ERICA}`);
  texto = texto.replace(/\[\[[^\]]*\]\]/g, '');

  if (canal === 'whatsapp') {
    texto = texto.replace(/\*\*(.+?)\*\*/g, '*$1*');
  } else {
    texto = texto.replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*(.+?)\*/g, '$1');
  }

  saida.push({
    json: {
      canal,
      resposta: texto.slice(0, 3900),
      telefone: origem.telefone || '',
      phoneNumberId: origem.phoneNumberId || ''
    }
  });
}

return saida;
